declare(strict_types=1);
require_once dirname(__DIR__,2).'/config.php';
require_once BASE_PATH.'/shared/auth.php';require_once BASE_PATH.'/shared/database.php';require_once BASE_PATH.'/shared/cost-workbook.php';require_once BASE_PATH.'/shared/accounts-input-vat.php';
require_role('owner_admin');header('Content-Type: application/json; charset=utf-8');
function pc_reply(array $v,int $s=200):void{http_response_code($s);echo json_encode($v,JSON_UNESCAPED_SLASHES);exit;}
function pc_body():array{$v=json_decode((string)file_get_contents('php://input'),true);return is_array($v)?$v:[];}
function pc_num($v):float{return max(0,(float)str_replace([',','N$'],'',(string)$v));}
function pc_dec($v,int $places=8):string{return number_format((float)$v,$places,'.','');}
function pc_date($v):?string{$v=(string)$v;$d=DateTimeImmutable::createFromFormat('Y-m-d',$v);return$d&&$d->format('Y-m-d')===$v?$v:null;}
function pc_costs(float $amount,float $quantity,string $basis,string $treatment,float $rate):array{if($quantity<=0)throw new RuntimeException('Purchase quantity must be greater than zero.');$rate=$treatment==='standard'?$rate:0;if($basis==='inclusive'){$inc=$amount;$ex=$rate>0?$amount/(1+$rate/100):$amount;}else{$ex=$amount;$inc=$amount*(1+$rate/100);}return['ex'=>$ex,'inc'=>$inc,'unit_ex'=>$ex/$quantity,'unit_inc'=>$inc/$quantity];}
function pc_audit(PDO $pdo,string $type,int $id,string $action,$before,$after):void{$u=cw_user();$pdo->prepare('INSERT INTO cw_packaging_audit(entity_type,entity_id,action_key,before_json,after_json,actor_id,actor_name) VALUES(?,?,?,?,?,?,?)')->execute([$type,$id,$action,$before===null?null:json_encode($before),$after===null?null:json_encode($after),$u['id'],$u['name']]);}
try{$pdo=db();cw_install_schema($pdo);$action=(string)($_GET['action']??'bootstrap');if($_SERVER['REQUEST_METHOD']!=='GET')cw_require_csrf();
if($action==='bootstrap'){$types=$pdo->query('SELECT id,name FROM cw_packaging_types WHERE active=1 ORDER BY name')->fetchAll();$sizes=$pdo->query('SELECT id,label,measurement_type,base_value,base_unit FROM cw_size_conversions WHERE active=1 ORDER BY measurement_type,base_value')->fetchAll();$items=$pdo->query("SELECT i.id,i.item_name,t.name packaging_type,i.supplier_name,i.supplier_sku,i.active,c.* FROM cw_packaging_items i JOIN cw_packaging_types t ON t.id=i.packaging_type_id LEFT JOIN cw_packaging_item_costs c ON c.id=(SELECT x.id FROM cw_packaging_item_costs x WHERE x.packaging_item_id=i.id ORDER BY x.effective_date DESC,x.id DESC LIMIT 1) ORDER BY i.item_name")->fetchAll();$setups=$pdo->query("SELECT s.*,z.label size_label,COUNT(c.id) component_count,COALESCE(SUM(c.component_cost_ex),0) total_ex,COALESCE(SUM(c.component_cost_inc),0) total_inc FROM cw_packaging_setups s JOIN cw_size_conversions z ON z.id=s.size_conversion_id LEFT JOIN cw_packaging_setup_components c ON c.packaging_setup_id=s.id GROUP BY s.id ORDER BY s.active DESC,s.effective_date DESC,s.id DESC")->fetchAll();$missing=(int)$pdo->query("SELECT COUNT(*) FROM cw_size_conversions z WHERE z.active=1 AND NOT EXISTS(SELECT 1 FROM cw_packaging_setups s WHERE s.size_conversion_id=z.id AND s.active=1)")->fetchColumn();$average=(float)$pdo->query("SELECT COALESCE(AVG(x.total),0) FROM (SELECT SUM(c.component_cost_inc) total FROM cw_packaging_setups s JOIN cw_packaging_setup_components c ON c.packaging_setup_id=s.id WHERE s.active=1 GROUP BY s.id)x")->fetchColumn();pc_reply(['types'=>$types,'sizes'=>$sizes,'items'=>$items,'setups'=>$setups,'vat_rate'=>accounts_standard_vat_rate(),'summary'=>['items'=>count(array_filter($items,function($x){return(int)$x['active']===1;})),'setups'=>count(array_filter($setups,function($x){return(int)$x['active']===1;})),'missing'=>$missing,'average'=>pc_dec($average,2)]]);}
if($action==='save-item'){$b=pc_body();$id=(int)($b['id']??0);$name=trim((string)($b['item_name']??''));$type=(int)($b['packaging_type_id']??0);$date=pc_date($b['effective_date']??'');$quantity=pc_num($b['purchase_quantity']??0);$unit=trim((string)($b['purchase_unit']??''));$amount=pc_num($b['amount_entered']??0);$basis=(string)($b['cost_basis']??'inclusive');$treatment=(string)($b['vat_treatment']??'standard');$rate=accounts_standard_vat_rate();if($name===''||!$type||!$date||$unit==='')throw new RuntimeException('Item name, packaging type, effective date, purchase quantity and purchase unit are required.');if(!in_array($basis,['inclusive','exclusive'],true)||!in_array($treatment,['standard','zero_rated','exempt'],true))throw new RuntimeException('Select valid cost and VAT treatments.');$c=pc_costs($amount,$quantity,$basis,$treatment,$rate);$u=cw_user();$pdo->beginTransaction();$before=null;if($id){$st=$pdo->prepare('SELECT * FROM cw_packaging_items WHERE id=? FOR UPDATE');$st->execute([$id]);$before=$st->fetch();if(!$before)throw new RuntimeException('Packaging item not found.');$pdo->prepare('UPDATE cw_packaging_items SET item_name=?,packaging_type_id=?,supplier_name=?,supplier_sku=?,notes=?,updated_by=?,updated_by_name=? WHERE id=?')->execute([$name,$type,trim((string)($b['supplier_name']??'')),trim((string)($b['supplier_sku']??'')),trim((string)($b['notes']??'')),$u['id'],$u['name'],$id]);}else{$pdo->prepare('INSERT INTO cw_packaging_items(item_name,packaging_type_id,supplier_name,supplier_sku,notes,created_by,created_by_name) VALUES(?,?,?,?,?,?,?)')->execute([$name,$type,trim((string)($b['supplier_name']??'')),trim((string)($b['supplier_sku']??'')),trim((string)($b['notes']??'')),$u['id'],$u['name']]);$id=(int)$pdo->lastInsertId();}$last=$pdo->prepare('SELECT * FROM cw_packaging_item_costs WHERE packaging_item_id=? ORDER BY effective_date DESC,id DESC LIMIT 1');$last->execute([$id]);$prior=$last->fetch();$changed=!$prior||$prior['effective_date']!==$date||abs((float)$prior['purchase_quantity']-$quantity)>.0000001||abs((float)$prior['amount_entered']-$amount)>.0000001||$prior['cost_basis']!==$basis||$prior['vat_treatment']!==$treatment||$prior['purchase_unit']!==$unit;if($changed)$pdo->prepare('INSERT INTO cw_packaging_item_costs(packaging_item_id,effective_date,purchase_quantity,purchase_unit,cost_basis,amount_entered,vat_rate,vat_treatment,cost_ex_vat,cost_inc_vat,unit_cost_ex_vat,unit_cost_inc_vat,created_by,created_by_name) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$date,pc_dec($quantity,6),$unit,$basis,pc_dec($amount,6),pc_dec($rate,4),$treatment,pc_dec($c['ex']),pc_dec($c['inc']),pc_dec($c['unit_ex'],10),pc_dec($c['unit_inc'],10),$u['id'],$u['name']]);pc_audit($pdo,'item',$id,$before?'updated':'created',$before,['item_name'=>$name,'cost'=>$c,'effective_date'=>$date]);$pdo->commit();pc_reply(['ok'=>true,'id'=>$id,'message'=>$changed?'Packaging item saved with a new effective-dated cost.':'Packaging item details saved.']);}
if($action==='save-setup'){$b=pc_body();$id=(int)($b['id']??0);$name=trim((string)($b['setup_name']??''));$size=(int)($b['size_conversion_id']??0);$scope=(string)($b['scope_type']??'default');$ref=trim((string)($b['scope_reference']??''));$label=trim((string)($b['scope_label']??''));$date=pc_date($b['effective_date']??'');$components=(array)($b['components']??[]);if($name===''||!$size||!$date||!in_array($scope,['default','category','product'],true))throw new RuntimeException('Setup name, product size, scope and effective date are required.');if($scope!=='default'&&$ref==='')throw new RuntimeException('Category and product setups require a scope reference.');if(!$components)throw new RuntimeException('Add at least one packaging component.');$dup=$pdo->prepare('SELECT id FROM cw_packaging_setups WHERE size_conversion_id=? AND scope_type=? AND scope_reference=? AND active=1 AND id<>? LIMIT 1');$dup->execute([$size,$scope,$scope==='default'?'':$ref,$id]);if($dup->fetchColumn())throw new RuntimeException('An active setup already exists for this size and scope. Deactivate it before creating another.');$u=cw_user();$pdo->beginTransaction();$before=null;if($id){$st=$pdo->prepare('SELECT * FROM cw_packaging_setups WHERE id=? FOR UPDATE');$st->execute([$id]);$before=$st->fetch();if(!$before)throw new RuntimeException('Packaging setup not found.');$pdo->prepare('UPDATE cw_packaging_setups SET setup_name=?,size_conversion_id=?,scope_type=?,scope_reference=?,scope_label=?,effective_date=?,updated_by=?,updated_by_name=? WHERE id=?')->execute([$name,$size,$scope,$scope==='default'?'':$ref,$scope==='default'?'Global default':$label,$date,$u['id'],$u['name'],$id]);$pdo->prepare('DELETE FROM cw_packaging_setup_components WHERE packaging_setup_id=?')->execute([$id]);}else{$pdo->prepare('INSERT INTO cw_packaging_setups(setup_name,size_conversion_id,scope_type,scope_reference,scope_label,effective_date,created_by,created_by_name) VALUES(?,?,?,?,?,?,?,?)')->execute([$name,$size,$scope,$scope==='default'?'':$ref,$scope==='default'?'Global default':$label,$date,$u['id'],$u['name']]);$id=(int)$pdo->lastInsertId();}$ins=$pdo->prepare('INSERT INTO cw_packaging_setup_components(packaging_setup_id,packaging_item_id,packaging_cost_id,quantity,waste_percent,unit_cost_ex_snapshot,unit_cost_inc_snapshot,component_cost_ex,component_cost_inc,display_order) VALUES(?,?,?,?,?,?,?,?,?,?)');$seen=[];$totEx=0;$totInc=0;foreach($components as $ix=>$component){$item=(int)($component['packaging_item_id']??0);$qty=pc_num($component['quantity']??0);$waste=pc_num($component['waste_percent']??0);if(!$item||$qty<=0||isset($seen[$item]))throw new RuntimeException('Each component needs a unique active packaging item and quantity greater than zero.');$seen[$item]=1;$st=$pdo->prepare('SELECT c.* FROM cw_packaging_items i JOIN cw_packaging_item_costs c ON c.packaging_item_id=i.id WHERE i.id=? AND i.active=1 AND c.effective_date<=? ORDER BY c.effective_date DESC,c.id DESC LIMIT 1');$st->execute([$item,$date]);$cost=$st->fetch();if(!$cost)throw new RuntimeException('Every component needs an effective packaging cost on or before the setup date.');$mult=$qty*(1+$waste/100);$ex=$mult*(float)$cost['unit_cost_ex_vat'];$inc=$mult*(float)$cost['unit_cost_inc_vat'];$totEx+=$ex;$totInc+=$inc;$ins->execute([$id,$item,$cost['id'],pc_dec($qty,6),pc_dec($waste,4),$cost['unit_cost_ex_vat'],$cost['unit_cost_inc_vat'],pc_dec($ex),pc_dec($inc),$ix]);}pc_audit($pdo,'setup',$id,$before?'updated':'created',$before,['setup_name'=>$name,'total_ex'=>$totEx,'total_inc'=>$totInc]);$pdo->commit();pc_reply(['ok'=>true,'id'=>$id,'total_ex'=>pc_dec($totEx),'total_inc'=>pc_dec($totInc),'message'=>'Packaging size setup saved with cost snapshots.']);}
if($action==='toggle'){$b=pc_body();$type=(string)($b['type']??'');$id=(int)($b['id']??0);$active=!empty($b['active'])?1:0;if(!in_array($type,['item','setup'],true)||!$id)throw new RuntimeException('Invalid packaging record.');$table=$type==='item'?'cw_packaging_items':'cw_packaging_setups';$pdo->prepare("UPDATE {$table} SET active=? WHERE id=?")->execute([$active,$id]);pc_audit($pdo,$type,$id,$active?'reactivated':'deactivated',null,['active'=>$active]);pc_reply(['ok'=>true]);}
pc_reply(['error'=>'Unknown action.'],404);
}catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();pc_reply(['error'=>$e->getMessage()],400);}
